// テーマ。資料ごとに、6 つのアクセント色の値と意味の名前・フォントを決める (計画の R11)。
// 図形の色はテーマの色の名前で指定し、色の値はテーマだけが持つ。

/** アクセント色。color は 16 進数 6 桁の RGB の値 (例: "0F8B8D")、meaning はその色に割り当てた意味 (例: "新しい版")。 */
export interface AccentColor {
  color: string;
  meaning: string;
}

/**
 * 資料のテーマ。
 * colors はアクセント色以外の 6 色 (dk1 は文字、lt1 は背景、dk2 は補助の文字、lt2 は補助の背景、hlink はリンク、folHlink は開いたリンク)。
 * accents は 6 つのアクセント色で、どれも省略できない。
 * name はテーマの名前で、PowerPoint のファイルに書き込む。
 */
export interface Theme {
  name: string;
  fonts: {
    heading: string;
    body: string;
  };
  colors: {
    dk1: string;
    lt1: string;
    dk2: string;
    lt2: string;
    hlink: string;
    folHlink: string;
  };
  accents: {
    accent1: AccentColor;
    accent2: AccentColor;
    accent3: AccentColor;
    accent4: AccentColor;
    accent5: AccentColor;
    accent6: AccentColor;
  };
}

/** テーマの 12 色の名前。PowerPoint のファイルの形式の配色の名前と同じ。 */
export type SchemeColorName = keyof Theme["colors"] | keyof Theme["accents"];

/** テーマの 12 色の名前を、配色の順序で並べた配列。 */
export const SCHEME_COLOR_NAMES: readonly SchemeColorName[] = [
  "dk1",
  "lt1",
  "dk2",
  "lt2",
  "accent1",
  "accent2",
  "accent3",
  "accent4",
  "accent5",
  "accent6",
  "hlink",
  "folHlink",
];

/** テーマの 12 色の名前と値の対応を返す。PowerPoint のファイルと Google スライドに配色を書き込むときに使う。 */
export function schemeColorValues(theme: Theme): Record<SchemeColorName, string> {
  const { colors, accents } = theme;
  return {
    ...colors,
    accent1: accents.accent1.color,
    accent2: accents.accent2.color,
    accent3: accents.accent3.color,
    accent4: accents.accent4.color,
    accent5: accents.accent5.color,
    accent6: accents.accent6.color,
  };
}

const RGB_HEX = /^[0-9A-Fa-f]{6}$/;

/**
 * テーマの値の誤りを、すべて集めて返す。誤りが無ければ空の配列を返す。
 * 型では検査できない、色の値の形 (16 進数 6 桁。"#" を付けない) と、空の名前・フォント・意味を検査する。
 */
export function checkTheme(theme: Theme): string[] {
  const errors: string[] = [];
  if (theme.name.trim() === "") errors.push("テーマの name が空");
  if (theme.fonts.heading.trim() === "") errors.push("テーマの fonts.heading が空");
  if (theme.fonts.body.trim() === "") errors.push("テーマの fonts.body が空");
  const values = schemeColorValues(theme);
  for (const name of SCHEME_COLOR_NAMES) {
    const value = values[name];
    if (!RGB_HEX.test(value)) {
      errors.push(`テーマの色 ${name} の値 ${JSON.stringify(value)} が、16 進数 6 桁 (例: "0F8B8D") ではない`);
    }
  }
  for (const [name, accent] of Object.entries(theme.accents)) {
    if (accent.meaning.trim() === "") errors.push(`テーマの色 ${name} の meaning が空`);
  }
  return errors;
}
// 資料ごとのスクリプト deck.ts が、名前 slide-deck で import type する型 (計画の KTD2)。
// deck.ts はプラグインのモジュールを実行時に import しないので、ここからは型だけを書き出す。

import type { Parts } from "./data/parts.ts";
import type { SlideFigure } from "./data/types.ts";
import type { Theme } from "./data/theme.ts";

export type {
  ArrowOptions,
  BadgeOptions,
  BoxOptions,
  BulletsOptions,
  CardOptions,
  MarginInput,
  Parts,
  RunInput,
  TextOptions,
} from "./data/parts.ts";
export type { AccentColor, SchemeColorName, Theme } from "./data/theme.ts";
export type {
  Deck,
  Fill,
  LineElement,
  Margin,
  Outline,
  Paragraph,
  Rect,
  ShapeElement,
  ShapeGeometry,
  ShapeKind,
  Slide,
  SlideElement,
  SlideFigure,
  TextBody,
  TextBoxElement,
  TextRun,
  ThemeColorName,
} from "./data/types.ts";

/** 資料ごとのスクリプトの関数が返す値。資料のテーマと、キーごとの図。 */
export interface DeckScriptResult {
  theme: Theme;
  slides: SlideFigure[];
}

/**
 * 資料ごとのスクリプトが default export する関数の型。
 * 部品の関数の集まりを引数で受け取り、テーマとキーごとの図を返す。
 */
export type DeckScript = (p: Parts) => DeckScriptResult;
// プラグイン slide-deck のスキルが実行する入口。
// サブコマンドごとの --help が、引数・出力・終了コードの SSOT (計画 docs/plans/2026-11-09-2343-feat-slide-deck-plugin-plan.md の KTD17)。
// 終了コードは、どのサブコマンドも、成功 0・検査の指摘あり 1・実行の誤り (ライブラリが無い・入力の形が違うなど) 2 に分ける。

import { parseArgs } from "node:util";
import { formatStatus, inspect, install, REQUIRED_NODE_MAJOR, SetupError, statusExitCode } from "./setup/setup.ts";

const USAGE_PREFIX = "使い方: node <プラグインのディレクトリ>/src/cli.ts";

const CACHE_DIR_HELP = `キャッシュのディレクトリ:
  環境変数 SLIDE_DECK_CACHE_DIR があればその場所そのもの、無ければ $XDG_CACHE_HOME/akm-claude-plugins/slide-deck
  (XDG_CACHE_HOME も無ければ ~/.cache/akm-claude-plugins/slide-deck)。
  venv は venv-<ハッシュ値>/ に、node_modules は node-<ハッシュ値>/node_modules/ に入れる。ハッシュ値は、venv が
  プラグインの uv.lock と .python-version の内容から、node_modules が package-lock.json の内容から求めた SHA-256 の先頭 16 文字。
  ロックファイルを変えないバージョンのプラグインどうしは、同じものを使う。`;

interface Command {
  readonly summary: string;
  readonly help: string;
  readonly run: () => number;
}

const COMMANDS: Readonly<Record<string, Command>> = {
  "setup status": {
    summary: "ライブラリがキャッシュのディレクトリに入っているかと、取得するものを示す (何も入れない)",
    help: `${USAGE_PREFIX} setup status

ライブラリ (Python の venv と Node.js の node_modules) が、キャッシュのディレクトリに入っているかを示す。何も入れない。
スキルは、入れるものがあれば (終了コード 1)、出力の「取得するもの」とキャッシュのディレクトリを利用者に示して承認を得てから、
setup install を実行する。

${CACHE_DIR_HELP}

引数:
  なし。--help (-h) でこの説明を示す。

出力 (標準出力):
  キャッシュのディレクトリ、Node.js のバージョン、uv と npm のパス (無ければ「無い」)、
  venv と node_modules の状態とパス。状態は次のどれか。
    入っている
    無い
    作りかけ (venv だけ。ディレクトリがあるのにフラグファイル installed が無い。setup install が uv sync をやり直す)
    壊れている (node_modules だけ。node-<ハッシュ値>/ があるのに node_modules/.package-lock.json が無い)
  入れるものがあれば「取得するもの:」の後に、取得するもの (Python のバージョンと、ロックファイルのバージョンのパッケージ) を示す。
  入れられない理由があれば「入れられない理由:」の後に、理由と直し方を示す。
  setup install が npm ci の途中で強制終了されて残った一時的な名前のディレクトリ (node-<ハッシュ値>.<6 文字>) があれば、
  「残っている一時的なディレクトリ」の後にそのパスを示す。setup install を実行していなければ消してよい。終了コードには影響しない。

終了コード:
  0  venv と node_modules がどちらも入っている
  1  入れるものがある (setup install で入れられる)
  2  入れられない。Node.js が ${String(REQUIRED_NODE_MAJOR)} 未満、入れるのに要る uv か npm が PATH に無い、node_modules のディレクトリが壊れている、
     のどれか。出力の「入れられない理由:」に直し方を示す
`,
    run: () => {
      const report = inspect();
      process.stdout.write(formatStatus(report));
      return statusExitCode(report);
    },
  },
  "setup install": {
    summary: "入っていないライブラリだけを、キャッシュのディレクトリに入れる",
    help: `${USAGE_PREFIX} setup install

入っていないライブラリだけを、プラグインに同梱したロックファイルのバージョンで、キャッシュのディレクトリに入れる。
入っているものには何もしない。スキルは、setup status の結果を利用者に示して承認を得てから実行する。
  venv:         uv sync --frozen --no-dev を、環境変数 UV_PROJECT_ENVIRONMENT に venv-<ハッシュ値>/ を指定して実行し、
                完了したらフラグファイル installed を作る。作りかけの venv (フラグファイルが無い) は、uv sync をやり直す。
  node_modules: 一時的な名前のディレクトリで npm ci --omit=dev を実行し、完了したら node-<ハッシュ値>/ に改名する。
                改名の前に、同時に実行した別の setup install が node-<ハッシュ値>/ を作り終えていたら、入ったものとして扱う。

${CACHE_DIR_HELP}

引数:
  なし。--help (-h) でこの説明を示す。

出力:
  標準出力に、実行することと、入れたディレクトリを示す。
  失敗したときは、標準エラー出力に理由と直し方を示す。uv sync か npm ci が失敗したときは、その標準エラー出力も示す。

終了コード:
  0  入れた (入れるものが無かったときを含む)
  2  入れられない (setup status の終了コード 2 と同じ条件)。何も入れずに終了する。
     または、uv sync か npm ci が失敗した。別の方法を試さずに、失敗した時点で終了する。
     npm ci の失敗では一時的な名前のディレクトリを消す。uv sync の失敗では、venv のディレクトリができていれば、
     フラグファイルを作らずに残す (失敗の文が、残したか、作る前に失敗したかを示す)
`,
    run: () => {
      install({ log: (line) => process.stdout.write(`${line}\n`) });
      return 0;
    },
  },
};

const TOP_HELP = `${USAGE_PREFIX} <サブコマンド> [--help]

サブコマンド:
${Object.entries(COMMANDS)
  .map(([name, c]) => `  ${name.padEnd(14)} ${c.summary}`)
  .join("\n")}

サブコマンドごとの引数・出力・終了コードは、<サブコマンド> --help で示す。
`;

function main(argv: readonly string[]): number {
  let help: boolean;
  let positionals: string[];
  try {
    const parsed = parseArgs({
      args: [...argv],
      options: { help: { type: "boolean", short: "h" } },
      allowPositionals: true,
      strict: true,
    });
    help = parsed.values.help ?? false;
    positionals = parsed.positionals;
  } catch (e) {
    process.stderr.write(`${e instanceof Error ? e.message : String(e)}\n\n${TOP_HELP}`);
    return 2;
  }
  const name = positionals.join(" ");
  const command = COMMANDS[name];
  if (command === undefined) {
    if (help && (name === "" || name === "setup")) {
      process.stdout.write(TOP_HELP);
      return 0;
    }
    process.stderr.write(`${name === "" ? "サブコマンドを指定する" : `存在しないサブコマンド: ${name}`}\n\n${TOP_HELP}`);
    return 2;
  }
  if (help) {
    process.stdout.write(command.help);
    return 0;
  }
  try {
    return command.run();
  } catch (e) {
    // 想定していない誤りも、終了コード 1 (検査の指摘あり) と区別できるよう、実行の誤り 2 にする
    process.stderr.write(`${e instanceof SetupError ? e.message : e instanceof Error ? (e.stack ?? e.message) : String(e)}\n`);
    return 2;
  }
}

process.exitCode = main(process.argv.slice(2));
