  add: (s: ReturnType<typeof slide>, t: string) => void,
  t: string,
): FitIssue | null {
  const fig = slide(key);
  add(fig, t);
  const [box] = fig.elements;
  if (box?.kind !== "textBox") {
    throw new Error(`関数 ${element} が文字の箱を作らなかった (キー ${key})`);
  }
  return estimateBody(key, element, box, box.text);
}

