  readonly pptx: string | null;
  /** テーマの色を書き込む処理の出力 */
  readonly applyThemeOutput: string;
  /** validate.py の結果。check に指摘があれば null */
  readonly validate: ValidateResult | null;
}

/**
 * 資料のディレクトリを検査し、指摘が無ければ build/deck.pptx を書き、テーマの色を書き込み、形式を検査する。
 * 前に書いた build/deck.pptx は、最初に消す (ファイルがあることと、最後の実行が書いたことを一致させるため)。
 * テーマの色の書き込みが失敗したら、書いたファイルも消す。validate.py が形式の誤りを見つけたときは、調べられるようファイルを残す
 */
export async function buildPptx(deckDir: string, options: PptxOptions): Promise<PptxReport> {
  const env = options.env ?? process.env;
  const skill = pptxSkill(options.skillDir);
  const cache = installedCache(options);
  if (venvState(cache) !== "installed") {
    throw new ExecutionError(
      `ライブラリ (Python の venv) が、キャッシュのディレクトリ ${cache.venvDir} に入っていない。` +
        "サブコマンド setup status で状態を確認し、setup install で入れる",
    );
  }
  const paths = deckPaths(deckDir);
  const pptxPath = join(paths.buildDir, "deck.pptx");
  const themePath = join(paths.buildDir, "theme.json");
  rmSync(pptxPath, { force: true });

  const check = await checkDeck(deckDir, options);
  if (check.deck === null) return { check, pptx: null, applyThemeOutput: "", validate: null };

  writeFileSync(pptxPath, await renderPptx(check.deck, loadPptxGen(cache.nodeModulesDir)));
182:前に書いた build/deck.pptx は、最初に消す。check の検査の内容と順序:
    ...textBodyOptions(e.text),
  };
  if (e.name !== null) options.objectName = e.name;
  s.addText(toTextProps(e.text.paragraphs), options);
}

function addLine(pres: Presentation, s: PptxSlide, e: LineElement): void {
  // 矢じりは、始点 (beginArrowType) と終点 (endArrowType) に付ける。
  // 型 LineElement の endArrow は終点、startArrow は始点の矢じり (型の説明)
  const line: PptxGenJS.ShapeLineProps = lineOptions(e.color, e.width, e.dashed);
  if (e.endArrow) line.endArrowType = "triangle";
  if (e.startArrow) line.beginArrowType = "triangle";
  s.addShape(pres.ShapeType.line, { x: e.x, y: e.y, w: e.w, h: e.h, flipH: e.flipH, flipV: e.flipV, line });
}

/** 部品の関数 title か takeaway が作る文字の箱を取り出す */
function fixedBox(add: (s: SlideFigure, t: string) => void, key: string, t: string): TextBoxElement {
  const fig = emptyFigure(key);
  add(fig, t);
  const [box] = fig.elements;
  if (box?.kind !== "textBox") throw new Error(`題名か一言の部品の関数が、文字の箱を作らなかった (キー ${key})`);
  return box;
}

/**
 * 題名のプレースホルダーを持つレイアウトを作る。位置と書式は、部品の関数 title が作る箱と同じにする
      return e.text;
  }
}

/** 部品の関数 title か takeaway が作る文字の箱で、題名か一言を見積もる。 */
function estimateFixedBox(
  key: string,
  element: "title" | "takeaway",
  add: (s: SlideFigure, t: string) => void,
  t: string,
): FitIssue | null {
  const fig = slide(key);
  add(fig, t);
  const [box] = fig.elements;
  if (box?.kind !== "textBox") {
    throw new Error(`関数 ${element} が文字の箱を作らなかった (キー ${key})`);
  }
  return estimateBody(key, element, box, box.text);
}

